      "فيقوم ليعمل شيئا. أي شيء. يرتب خزانة، أو يفتح مشروعا كان قد أجله، أو يضع خطة لشيء بعد شهرين.",
      "وهو ليس مجتهدا. هو فقط لم يستطع أن يجلس."
