      "وشيء ينبغي أن يقال بصراحة: نحن نقرأ ما وصلنا منك. فلو كان ثم موقف مهم في حياتك لم يخطر ببالك وأنت تجيب، فهو لم يدخل في الحساب. وأنت وحدك تعرف هذا."
