      "يعني ماذا؟",
      "المعلومة تعطيك شيئا لم تكن تعرفه. كأن يقول لك أحد السعر، أو يقول لك هذا الطبيب جيد.",
      "والإشارة التي تنتظرها أنت لا تضيف لك أي معلومة جديدة. هي تقول لك شيئا واحدا فقط: نعم، امض.",
      "فحركتك لا ينقصها علم لتتحرك. ينقصها من يصدق عليها.",
