      "ففي المكان الذي يقف فيه الناس ينتظرون توضيحا، أو إذنا، أو ظرفا أفضل، تكون أنت قد بدأت.",
      "والذي ينفذ في الدنيا ينفذه ناس لا يحتملون أن يبقى الأمر معلقا.",
