      "فقبل حركة جسدك بلحظة، وقع نظرك على شيء واحد في الموقف دون بقية الأشياء.",
      "من اختار هذا الشيء؟",
      "وهل تعرف ما لم تره أصلا وأنت واقف هناك؟"
