    "m2.a2.experiment.type7": [
      "في لحظة واحدة حسنة تمر عليك هذا الأسبوع:",
      "أتقدر أن تجلس فيها إلى آخرها دون أن تفتح ما بعدها؟",
      "دون أن تقول ينبغي أن نكرر هذا، ودون أن تحجز الموعد القادم، ودون أن تفكر في التطوير.",
      "لحظة واحدة فقط، تنتهي عند نفسها.",
      "والملل وأنت فيها جزء من التجربة، لا علامة على فشلها.",
      "وبعدها ثم ثلاثة أشياء تستحق الوقفة:",
      "في أي لحظة بالضبط جاءك الاحتمال الآخر؟",
      "وماذا فعل جسدك عندها؟ أغيرت جلستك، أم قمت، أم فتحت الهاتف؟",
      "وما الذي كان يمكن أن يحدث لو فتحته؟",
      "وسطر واحد للمرآة القادمة:",
      "حين أغلقت الباب الآخر وبقيت في اللحظة، جاءك إحساس. أوصل كما هو؟ أم تحول إلى شيء آخر بسرعة؟"
    ],

