      "فليس ثم نقطة ثابتة تقيس منها نفسك.",
      "ولهذا تحس بقوة وسط الناس، وبضياع حين تجلس وحدك.",
      "وهذا الفرق ليس تناقضا. هذا أن الكشاف لا عمل له حين يخلو المكان."
