      "فإن عرفت إجابتك، وعرفت أيضا أنها رأيك أنت لا رأي المكان، فالحركة في يدك.",
      "وإن بحثت عن الإجابة في وجوه الجالسين، فالحركة هي التي تحركك.",
      "وثم فرق مهم لا بد أن يقال: أن تجاري المكان أحيانا ليس مشكلة. الفرق أن تكون عارفا أنك اخترت."
