        "ومعنى هذا أن إجاباتك كانت صادقة، وأنها جاءت من موضع أنت مستريح إليه. وقد قرأت الأداة هذا الموضع، ورأت من أين يصلك أنك بخير.",
        "والذي لا تراه الأداة أن الموضع ذاته قد يعمل عندك بحالين مختلفين تماما، والفارق بينهما ليس في الإجابات. الفارق فيما يجري لك بعد أن يتحقق ما تنتظره.",
        "فاقرأ ما يلي وأنت منتبه إلى هذا."
